namespace RonSijm.FluidHumidifier.Factories.Bedrock;

public class EnforcedGuardrailConfigurationFactory(string resourceName = null, Action<Humidifier.Bedrock.EnforcedGuardrailConfiguration> factoryAction = null) : ResourceFactory<Humidifier.Bedrock.EnforcedGuardrailConfiguration>(resourceName)
{

    internal InnerEnforcedGuardrailConfigurationModelEnforcementFactory ModelEnforcementFactory { get; set; }

    internal InnerEnforcedGuardrailConfigurationSelectiveContentGuardingFactory SelectiveContentGuardingFactory { get; set; }

    protected override Humidifier.Bedrock.EnforcedGuardrailConfiguration Create()
    {
        var enforcedGuardrailConfigurationResult = CreateEnforcedGuardrailConfiguration();
        factoryAction?.Invoke(enforcedGuardrailConfigurationResult);

        return enforcedGuardrailConfigurationResult;
    }

    private Humidifier.Bedrock.EnforcedGuardrailConfiguration CreateEnforcedGuardrailConfiguration()
    {
        var enforcedGuardrailConfigurationResult = new Humidifier.Bedrock.EnforcedGuardrailConfiguration
        {
            GivenName = InputResourceName,
        };

        return enforcedGuardrailConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.EnforcedGuardrailConfiguration result)
    {
        base.CreateChildren(result);

        result.ModelEnforcement ??= ModelEnforcementFactory?.Build();
        result.SelectiveContentGuarding ??= SelectiveContentGuardingFactory?.Build();
    }

} // End Of Class

